window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c9a0be0a8c5a657d"]={"versions": [{"id": "FIG-c9a0be0a8c5a657d", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine Diagram) zur Modellierung des globalen Überwachungsstatus (<code>Global Supervision Status</code>) innerhalb des Platform Health Management (PHM) der AUTOSAR Adaptive Platform. Das Diagramm definiert die Zustände und Zustandsübergänge bei der Aggregation lokaler Überwachungsergebnisse über den gesamten Lebenszyklus einer Funktionsgruppe oder Plattforminstanz hinweg.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert fünf Hauptzustände, drei Verzweigungsknoten (Choice/Junction-Pseudozustände) sowie einen initialen Pseudozustand:</p>\n<ul class=\"fig-list\"><li><strong>Initialzustand</strong>: Schwarzer Vollkreis mit initialer Transition (1).\n</li><li><strong>Zustände</strong>:\n<ul class=\"fig-list\"><li><code>GLOBAL_STATUS_DEACTIVATED</code>: Ruhezustand der Überwachung vor Aktivierung oder nach Rückführung.\n</li><li><code>GLOBAL_STATUS_OK</code>: Regulärer Betriebszustand mit fehlerfreier Überwachung.\n</li><li><code>GLOBAL_STATUS_FAILED</code>: Fehlerzustand bei Nichterfüllung lokaler Überwachungskriterien (tolerierbare oder noch nicht eskalierte Fehler).\n</li><li><code>GLOBAL_STATUS_EXPIRED</code>: Kritischer Fehlerzustand nach Ablauf von Fehlerakzeptanz- oder Reaktionszeiten.\n</li><li><code>GLOBAL_STATUS_STOPPED</code>: Gestoppter End- oder Haltezustand der Überwachung.\n</li></ul>\n</li><li><strong>Verzweigungen</strong>: Rauten zur bedingten Weiterleitung basierend auf dem aggregierten Ergebnis lokaler Checkpoints und Supervisions.\n</li><li><strong>Schnittstellen</strong>: Übergänge sind abstrakt als nummerierte Transitionen (1) bis (20) modelliert.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Initialisierung</strong>: Eintritt über Pseudozustand (1) in <code>GLOBAL_STATUS_DEACTIVATED</code>.\n</li><li><strong>Aktivierung &amp; Verzweigung aus Deaktiviert</strong>: Transition von <code>GLOBAL_STATUS_DEACTIVATED</code> führt auf zwei kaskadierte Rauten:\n<ul class=\"fig-list\"><li>Bei fehlerfreier Prüfung Übergang (2) nach <code>GLOBAL_STATUS_OK</code>.\n</li><li>Bei initialem Fehler Übergang (3) nach <code>GLOBAL_STATUS_FAILED</code>.\n</li><li>Bei abgelaufener Frist Übergang (4) nach <code>GLOBAL_STATUS_EXPIRED</code>.\n</li><li>Bei direktem Abbruch/Stopp Übergang (5) nach <code>GLOBAL_STATUS_STOPPED</code>.\n</li></ul>\n</li><li><strong>Übergänge aus GLOBAL_STATUS_OK</strong>:\n<ul class=\"fig-list\"><li>Rückkehr nach Deaktivierung über (6) nach <code>GLOBAL_STATUS_DEACTIVATED</code>.\n</li><li>Fehlerdetektion über (7) direkt nach <code>GLOBAL_STATUS_FAILED</code>.\n</li><li>Verzweigungsraute aus <code>GLOBAL_STATUS_OK</code> führt über (8) nach <code>GLOBAL_STATUS_EXPIRED</code> oder über (9) nach <code>GLOBAL_STATUS_STOPPED</code>.\n</li></ul>\n</li><li><strong>Übergänge aus GLOBAL_STATUS_FAILED</strong>:\n<ul class=\"fig-list\"><li>Erholung über (10) zurück nach <code>GLOBAL_STATUS_OK</code>.\n</li><li>Verzweigungsraute aus <code>GLOBAL_STATUS_FAILED</code> führt über (11) nach <code>GLOBAL_STATUS_EXPIRED</code> oder über (12) nach <code>GLOBAL_STATUS_STOPPED</code>.\n</li><li>Re-Deaktivierung über (14) nach <code>GLOBAL_STATUS_DEACTIVATED</code>.\n</li></ul>\n</li><li><strong>Übergänge aus GLOBAL_STATUS_EXPIRED</strong>:\n<ul class=\"fig-list\"><li>Eskalation über (13) nach <code>GLOBAL_STATUS_STOPPED</code>.\n</li><li>Re-Deaktivierung über (15) nach <code>GLOBAL_STATUS_DEACTIVATED</code>.\n</li><li>Wiederherstellung über (17) nach <code>GLOBAL_STATUS_FAILED</code> oder über (18) nach <code>GLOBAL_STATUS_OK</code>.\n</li></ul>\n</li><li><strong>Übergänge aus GLOBAL_STATUS_STOPPED</strong>:\n<ul class=\"fig-list\"><li>Rückführung über (16) nach <code>GLOBAL_STATUS_DEACTIVATED</code>.\n</li><li>Wiederaufnahme/Fehlerzustand über (19) nach <code>GLOBAL_STATUS_FAILED</code>.\n</li><li>Direkte Reaktivierung über (20) nach <code>GLOBAL_STATUS_OK</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Spezifikation des Zustandsautomaten für Implementierer des Platform Health Management (PHM). Softwarekomponenten müssen die Statuswerte exakt abbilden und die definierten Transitionen anhand konfigurierter Bedingungen (Wächterbedingungen, Checkpoint-Resultate, Fristen) durchlaufen. Zu beachten ist, dass aus jedem aktiven Zustand Pfade in finale/deaktivierte Zustände existieren, einschließlich zyklischer Reaktivierungspfade direkt aus <code>GLOBAL_STATUS_STOPPED</code>.</p>"}, {"id": "FIG-e06124fedc0ba091", "releases": ["R22-11", "R23-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine Diagram) zur Modellierung des globalen Überwachungsstatus (<code>Global Supervision Status</code>) innerhalb des Platform Health Management (PHM) der AUTOSAR Adaptive Platform. Das Diagramm definiert die Zustände und Zustandsübergänge bei der Aggregation lokaler Überwachungsergebnisse über den gesamten Lebenszyklus einer Funktionsgruppe oder Plattforminstanz hinweg.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert fünf Hauptzustände, drei Verzweigungsknoten (Choice/Junction-Pseudozustände) sowie einen initialen Pseudozustand:</p>\n<ul class=\"fig-list\"><li><strong>Initialzustand</strong>: Schwarzer Vollkreis mit initialer Transition (1).\n</li><li><strong>Zustände</strong>:\n<ul class=\"fig-list\"><li><code>kDEACTIVATED</code>: Ruhezustand der Überwachung vor Aktivierung oder nach Rückführung.\n</li><li><code>kOK</code>: Regulärer Betriebszustand mit fehlerfreier Überwachung.\n</li><li><code>kFAILED</code>: Fehlerzustand bei Nichterfüllung lokaler Überwachungskriterien.\n</li><li><code>kEXPIRED</code>: Kritischer Fehlerzustand nach Überschreiten von Überwachungslimits.\n</li><li><code>kSTOPPED</code>: Gestoppter Endzustand der Überwachung ohne ausgehende Transitionen.\n</li></ul>\n</li><li><strong>Verzweigungen</strong>: Drei Rauten zur bedingten Weiterleitung basierend auf dem aggregierten Status lokaler Überwachungen.\n</li><li><strong>Schnittstellen</strong>: Übergänge sind als nummerierte Transitionen (1) bis (17) modelliert.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Initialisierung</strong>: Eintritt über Pseudozustand (1) in <code>kDEACTIVATED</code>.\n</li><li><strong>Aktivierung &amp; Verzweigung aus kDEACTIVATED</strong>: Transition führt auf zwei kaskadierte Rauten:\n<ul class=\"fig-list\"><li>Übergang (2) nach <code>kOK</code>.\n</li><li>Übergang (3) nach <code>kFAILED</code>.\n</li><li>Übergang (4) nach <code>kEXPIRED</code>.\n</li><li>Übergang (5) nach <code>kSTOPPED</code>.\n</li></ul>\n</li><li><strong>Übergänge aus kOK</strong>:\n<ul class=\"fig-list\"><li>Deaktivierung über (6) nach <code>kDEACTIVATED</code>.\n</li><li>Fehlerdetektion über (7) direkt nach <code>kFAILED</code>.\n</li><li>Verzweigungsraute aus <code>kOK</code> führt über (8) nach <code>kEXPIRED</code> oder über (9) nach <code>kSTOPPED</code>.\n</li></ul>\n</li><li><strong>Übergänge aus kFAILED</strong>:\n<ul class=\"fig-list\"><li>Erholung über (10) zurück nach <code>kOK</code>.\n</li><li>Verzweigungsraute aus <code>kFAILED</code> führt über (11) nach <code>kEXPIRED</code> oder über (12) nach <code>kSTOPPED</code>.\n</li><li>Re-Deaktivierung über (14) nach <code>kDEACTIVATED</code>.\n</li></ul>\n</li><li><strong>Übergänge aus kEXPIRED</strong>:\n<ul class=\"fig-list\"><li>Eskalation über (13) nach <code>kSTOPPED</code>.\n</li><li>Re-Deaktivierung über (15) nach <code>kDEACTIVATED</code>.\n</li><li>Wiederherstellung über (16) nach <code>kOK</code>.\n</li><li>Fehlerzustandsübergang über (17) nach <code>kFAILED</code>.\n</li></ul>\n</li><li><strong>Verhalten von kSTOPPED</strong>:\n<ul class=\"fig-list\"><li>Zustand fungiert als Senke/Terminalzustand; es existieren keine ausgehenden Transitionen.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Spezifikation der PHM-Zustandsmaschine gemäß C++-Bezeichnerkonventionen der AUTOSAR Adaptive Platform. Die Implementierung muss sicherstellen, dass <code>kSTOPPED</code> ein terminaler Zustand ohne direkte Reaktivierungspfade im globalen Überwachungsautomaten ist. Übergänge aus <code>kEXPIRED</code> sind auf <code>kDEACTIVATED</code> (15), <code>kOK</code> (16), <code>kFAILED</code> (17) und <code>kSTOPPED</code> (13) beschränkt.</p>"}, {"id": "FIG-6979f2ebbde49c7c", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine Diagram) zur Modellierung des globalen Überwachungsstatus (<code>Global Supervision Status</code>) innerhalb des Platform Health Management (PHM) der AUTOSAR Adaptive Platform. Das Diagramm definiert die Zustände und Zustandsübergänge bei der Aggregation lokaler Überwachungsergebnisse über den gesamten Lebenszyklus einer Funktionsgruppe oder Plattforminstanz hinweg.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert fünf Hauptzustände, drei Verzweigungsknoten (Choice/Junction-Pseudozustände) sowie einen initialen Pseudozustand:</p>\n<ul class=\"fig-list\"><li><strong>Initialzustand</strong>: Schwarzer Vollkreis mit initialer Transition (1).\n</li><li><strong>Zustände</strong>:\n<ul class=\"fig-list\"><li><code>kDEACTIVATED</code>: Ruhezustand der Überwachung vor Aktivierung oder nach Rückführung.\n</li><li><code>kOK</code>: Regulärer Betriebszustand mit fehlerfreier Überwachung.\n</li><li><code>kFAILED</code>: Fehlerzustand bei Nichterfüllung lokaler Überwachungskriterien.\n</li><li><code>kEXPIRED</code>: Kritischer Fehlerzustand nach Überschreiten von Überwachungslimits.\n</li><li><code>kSTOPPED</code>: Gestoppter Endzustand der Überwachung ohne ausgehende Transitionen.\n</li></ul>\n</li><li><strong>Verzweigungen</strong>: Drei Rauten zur bedingten Weiterleitung basierend auf dem aggregierten Status lokaler Überwachungen.\n</li><li><strong>Schnittstellen</strong>: Übergänge sind als nummerierte Transitionen (1) bis (17) modelliert.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Initialisierung</strong>: Eintritt über Pseudozustand (1) in <code>kDEACTIVATED</code>.\n</li><li><strong>Aktivierung &amp; Verzweigung aus kDEACTIVATED</strong>: Transition führt auf zwei kaskadierte Rauten:\n<ul class=\"fig-list\"><li>Übergang (2) nach <code>kOK</code>.\n</li><li>Übergang (3) nach <code>kFAILED</code>.\n</li><li>Übergang (4) nach <code>kEXPIRED</code>.\n</li><li>Übergang (5) nach <code>kSTOPPED</code>.\n</li></ul>\n</li><li><strong>Übergänge aus kOK</strong>:\n<ul class=\"fig-list\"><li>Deaktivierung über (6) nach <code>kDEACTIVATED</code>.\n</li><li>Fehlerdetektion über (7) direkt nach <code>kFAILED</code>.\n</li><li>Verzweigungsraute aus <code>kOK</code> führt über (8) nach <code>kEXPIRED</code> oder über (9) nach <code>kSTOPPED</code>.\n</li></ul>\n</li><li><strong>Übergänge aus kFAILED</strong>:\n<ul class=\"fig-list\"><li>Erholung über (10) zurück nach <code>kOK</code>.\n</li><li>Verzweigungsraute aus <code>kFAILED</code> führt über (11) nach <code>kEXPIRED</code> oder über (12) nach <code>kSTOPPED</code>.\n</li><li>Re-Deaktivierung über (14) nach <code>kDEACTIVATED</code>.\n</li></ul>\n</li><li><strong>Übergänge aus kEXPIRED</strong>:\n<ul class=\"fig-list\"><li>Eskalation über (13) nach <code>kSTOPPED</code>.\n</li><li>Re-Deaktivierung über (15) nach <code>kDEACTIVATED</code>.\n</li><li>Wiederherstellung über (16) nach <code>kOK</code>.\n</li><li>Fehlerzustandsübergang über (17) nach <code>kFAILED</code>.\n</li></ul>\n</li><li><strong>Verhalten von kSTOPPED</strong>:\n<ul class=\"fig-list\"><li>Zustand fungiert als Senke/Terminalzustand; es existieren keine ausgehenden Transitionen.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Spezifikation der PHM-Zustandsmaschine gemäß C++-Bezeichnerkonventionen der AUTOSAR Adaptive Platform. Die Implementierung muss sicherstellen, dass <code>kSTOPPED</code> ein terminaler Zustand ohne direkte Reaktivierungspfade im globalen Überwachungsautomaten ist. Übergänge aus <code>kEXPIRED</code> sind auf <code>kDEACTIVATED</code> (15), <code>kOK</code> (16), <code>kFAILED</code> (17) und <code>kSTOPPED</code> (13) beschränkt.</p>"}], "trans": [{"from": "FIG-c9a0be0a8c5a657d", "to": "FIG-e06124fedc0ba091", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Umbenennung aller Zustände von C-Style/Konstantenbezeichnern auf C++-Enumerationswerte (Präfix <code>GLOBAL_STATUS_</code> ersetzt durch <code>k</code>):\n<ul class=\"fig-list\"><li><code>GLOBAL_STATUS_DEACTIVATED</code> -&gt; <code>kDEACTIVATED</code>\n</li><li><code>GLOBAL_STATUS_OK</code> -&gt; <code>kOK</code>\n</li><li><code>GLOBAL_STATUS_FAILED</code> -&gt; <code>kFAILED</code>\n</li><li><code>GLOBAL_STATUS_EXPIRED</code> -&gt; <code>kEXPIRED</code>\n</li><li><code>GLOBAL_STATUS_STOPPED</code> -&gt; <code>kSTOPPED</code>\n</li></ul>\n</li><li>Übergangs-Pfeil (20) von <code>GLOBAL_STATUS_STOPPED</code> nach <code>GLOBAL_STATUS_OK</code> ist ersatzlos entfallen.\n</li><li>Umnummerierung der Rückführungen:\n<ul class=\"fig-list\"><li>Transition (16) führt von <code>kEXPIRED</code> nach <code>kOK</code> (in der Vorlage war dies Transition (18)).\n</li><li>Transition (15) führt unverändert von <code>kEXPIRED</code> nach <code>kDEACTIVATED</code>.\n</li><li>Die frühere Transition (16) von <code>GLOBAL_STATUS_STOPPED</code> nach <code>GLOBAL_STATUS_DEACTIVATED</code> sowie die Transitionen (18), (19) und (20) sind entfallen; der Zustand <code>kSTOPPED</code> besitzt keine ausgehenden Transitionen mehr (Final-/Senkenzustand bezüglich Reaktivierung).\n</li></ul>\n</li></ul>"}, {"from": "FIG-e06124fedc0ba091", "to": "FIG-6979f2ebbde49c7c", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-6979f2ebbde49c7c", "to": "FIG-e06124fedc0ba091", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
